<?php $i=$_['invoice'];?><!doctype html><html><head><meta charset="utf-8"><title><?php p($i['invoice_no']);?></title><style>@page{size:A4;margin:18mm}body{font-family:Arial,sans-serif;color:#222;font-size:12px}.head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:35px}.logo{max-width:220px;max-height:90px}.meta{text-align:right}h1{font-size:26px;font-weight:500}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{padding:9px;border-bottom:1px solid #aaa;text-align:left}.num{text-align:right}.totals{margin-left:auto;margin-top:24px;width:300px}.totals div{display:flex;justify-content:space-between;padding:6px}.gross{font-size:16px;border-top:2px solid #222;font-weight:bold}</style></head><body><div class="head"><div><?php if($_['logoDataUri']):?><img class="logo" src="<?php p($_['logoDataUri']);?>"><?php endif;?></div><div class="meta">Rechnungsentwurf<br><?php p($i['invoice_no']);?><br><?php p(date('d.m.Y',strtotime($i['invoice_date'])));?></div></div><h1>Rechnung</h1><p><strong><?php p($_['customer']['name']??'');?></strong><br><?php echo nl2br(htmlspecialchars((string)($_['customer']['address']??''),ENT_QUOTES));?></p><?php if($_['project']):?><p>Projekt: <?php p(($_['project']['project_no']??'').' '.($_['project']['title']??''));?></p><?php endif;?><table><thead><tr><th>Leistung</th><th class="num">Menge</th><th>Einheit</th><th class="num">Einzelpreis</th><th class="num">Gesamt</th></tr></thead><tbody><?php foreach($_['items'] as $x):?><tr><td><?php p($x['description']);?></td><td class="num"><?php p(number_format((float)$x['quantity'],2,',','.'));?></td><td><?php p($x['unit']);?></td><td class="num"><?php p(number_format((float)$x['unit_price'],2,',','.'));?> €</td><td class="num"><?php p(number_format((float)$x['total_price'],2,',','.'));?> €</td></tr><?php endforeach;?></tbody></table><div class="totals"><div><span>Netto</span><span><?php p(number_format((float)$i['net_amount'],2,',','.'));?> €</span></div><div><span>USt. <?php p(number_format((float)$i['vat_rate'],2,',','.'));?> %</span><span><?php p(number_format((float)$i['gross_amount']-(float)$i['net_amount'],2,',','.'));?> €</span></div><div class="gross"><span>Brutto</span><span><?php p(number_format((float)$i['gross_amount'],2,',','.'));?> €</span></div></div><script>window.print()</script></body></html>
